sys_script_fix.script:
(function() {
    var incidentGR = new GlideRecord('incident');
    incidentGR.addQuery('active', true); 
    incidentGR.query(); 

    var callerIncidents = {};

    while (incidentGR.next()) {
        var callerID = incidentGR.caller_id;  

        if (!callerID) continue;

        var callerName = callerID.getDisplayValue();  

        if (!callerIncidents[callerName]) {
            callerIncidents[callerName] = 0;
        }
        callerIncidents[callerName]++;
    }

    for (var caller in callerIncidents) {
        if (callerIncidents[caller] > 0) {
            gs.info(caller + ' - ' + callerIncidents[caller] + ' incidents');
        }
    }
})();
